tools.example:
// Study 1: acpr near field of the loudspeaker with efc1 (IntType = IntegralApproximation)
// Study 2: Ray Tracing
model.component("comp1").physics("rac").create("rext1", "ReleaseFromExteriorFieldCalculation", -1);
model.component("comp1").physics("rac").feature("rext1").set("x0", new String[]{"2", "1", "1.2"});
model.component("comp1").physics("rac").feature("rext1").set("Nw", "20000");

model.component("comp1").physics("rac").create("rpf1", "ReleaseFromPressureField", 2);
model.component("comp1").physics("rac").feature("rpf1").selection().named("nearfield_boundary");
// Study: Frequency Domain for acpr, then Ray Tracing using that solution

model.component("comp1").physics("rac").feature("op1").set("f", "f0");
model.study("std1").create("param", "Parametric");
model.study("std1").feature("param").set("pname", new String[]{"f0"});
model.study("std1").feature("param").set("plistarr", new String[]{"125 250 500 1000 2000 4000 8000"});
model.study("std1").create("rtrac", "RayTracing");
model.study("std1").feature("rtrac").set("tlist", "0 2.5");

// Application Library: Acoustics_Module/Building_and_Room_Acoustics/chamber_music_hall (Receiver 3D per octave band)
model.result().dataset().create("re1", "Receiver3D");
model.result().dataset("re1").set("data", "ray1");
model.result().dataset("re1").set("center", new String[]{"xr", "yr", "zr"});
model.result().dataset("re1").set("radiusinput", "user");
model.result().dataset("re1").set("radius", "0.3[m]");

// Application Library: Acoustics_Module/Aeroacoustics_and_Noise/helmholtz_resonator_with_flow_cgns
model.study().create("std2");
model.study("std2").create("mapp", "Mapping");
model.study("std2").feature("mapp").set("notstudy", "std1");
model.study().create("std3");
model.study("std3").create("freq", "Frequency");

// transmission loss of Acoustics_Module/Automotive/absorptive_muffler
model.result().create("pg3", "PlotGroup1D");
model.result("pg3").create("oct1", "OctaveBand");
model.result("pg3").feature("oct1").set("expr", "acpr.port1.P_in/(acpr.port4.P_out+acpr.port5.P_out+acpr.port6.P_out)");
model.result("pg3").feature("oct1").set("exprtype", "transfer");
model.result("pg3").feature("oct1").set("quantity", "continuous");
// or band values: set("quantity", "bandaveragepsd") with set("bandtype", "octave3")

// radiated sound power through a surface enclosing a vibrating panel
model.result().numerical().create("int1", "IntSurface");
model.result().numerical("int1").selection().named("enclosing_surface");
model.result().numerical("int1").set("expr", new String[]{"acpr.Ix*nx+acpr.Iy*ny+acpr.Iz*nz"});
model.result().numerical("int1").setResult();

// Application Library: Acoustics_Module/Automotive/absorptive_muffler (TL from port powers)
model.result().create("pg2", "PlotGroup1D");
model.result("pg2").create("glob1", "Global");
model.result("pg2").feature("glob1").set("expr", new String[]{"10*log10(acpr.port1.P_in/acpr.port2.P_out)"});
model.result("pg2").feature("glob1").set("descr", new String[]{"Transmission loss"});
